const devices = global.get('devices') || {};
const configs = global.get('device_configs') || {};

const msgs = [];

// Find all AC controllers and sort by device_id for fixed mapping
const acList = Object.keys(configs)
    .filter(id => configs[id].type === 'ac_controller')
    .sort();  // 0x336A=idx0 (Khu A), 0xC5A9=idx1 (Khu B)

// Publish AC status (index-based)
acList.forEach((id, idx) => {
    const d = devices[id];
    if (!d) return;
    const s = d.state || {};
    const powerStr = s.power === true ? 'ON' : (s.power === false ? 'OFF' : 'OFF');
    const onlineStr = s.online === true ? 'ON' : (s.online === false ? 'OFF' : 'OFF');
    msgs.push({ topic: 'bms/ac/' + idx + '/temperature', payload: String(s.temperature || 0) });
    msgs.push({ topic: 'bms/ac/' + idx + '/room_temp', payload: String(s.ambient_temp || 0) });
    msgs.push({ topic: 'bms/ac/' + idx + '/power', payload: powerStr });
    msgs.push({ topic: 'bms/ac/' + idx + '/fan', payload: String(s.fan_speed || 0) });
    msgs.push({ topic: 'bms/ac/' + idx + '/online', payload: onlineStr });
});

// Summary
const acDevs = acList.map(id => devices[id]).filter(d => d);
const acOn = acDevs.filter(d => d.state?.power).length;
const acAvg = acDevs.length > 0 ? Math.round(acDevs.reduce((sum, d) => sum + (d.state?.temperature || 0), 0) / acDevs.length) : 0;

msgs.push({ topic: 'bms/status/ac_on_count', payload: String(acOn) });
msgs.push({ topic: 'bms/status/ac_avg_temp', payload: String(acAvg) });

return [msgs];

const topic = msg.topic;
const payload = msg.payload;
const parts = topic.split('/');

const configs = global.get('device_configs') || {};

// Find all AC controllers and sort by device_id for fixed mapping
const acIds = Object.keys(configs)
    .filter(id => configs[id].type === 'ac_controller')
    .sort();  // 0x336A=idx0 (Khu A), 0xC5A9=idx1 (Khu B)

let deviceId = null;
let action = null;
let extra = null;

// bms/ac/0/power/set
if (parts[1] === 'ac' && parts[3] === 'power' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = acIds[idx];
    action = payload === 'ON' ? 'POWER_ON' : 'POWER_OFF';
}
// bms/ac/0/temperature/set
else if (parts[1] === 'ac' && parts[3] === 'temperature' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = acIds[idx];
    action = 'AC_SET';
    extra = { temp: parseInt(payload) };
}
// bms/ac/0/fan/set
else if (parts[1] === 'ac' && parts[3] === 'fan' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = acIds[idx];
    action = 'AC_SET';
    extra = { fan_speed: parseInt(payload) };
}

if (!deviceId) {
    node.warn('Unknown topic: ' + topic);
    return null;
}

const cfg = configs[deviceId];
if (!cfg) { node.warn('No config for ' + deviceId); return null; }

const ex = cfg.extra || {};
const gateway = cfg.gateway || ex.gateway;

// Build ZbSend
const writes = {};
if (action === 'POWER_ON') {
    writes[ex.power_attr || '0101'] = 1;
} else if (action === 'POWER_OFF') {
    writes[ex.power_attr || '0101'] = 0;
} else if (action === 'AC_SET') {
    writes[ex.ac_power_attr || '0101'] = 1;
    if (extra && extra.temp !== undefined) writes[ex.ac_temp_attr || '0202'] = extra.temp;
    if (extra && extra.fan_speed !== undefined) writes[ex.ac_mode_attr || '0405'] = extra.fan_speed;
}

msg.topic = 'cmnd/' + gateway + '/ZbSend';
msg.payload = JSON.stringify({ Device: deviceId, Write: writes });
// Optimistic update global state
const devices = global.get('devices') || {};
if (!devices[deviceId]) devices[deviceId] = { id: deviceId, type: 'ac_controller', state: {} };
if (!devices[deviceId].state) devices[deviceId].state = {};
if (action === 'POWER_ON') devices[deviceId].state.power = true;
if (action === 'POWER_OFF') devices[deviceId].state.power = false;
if (action === 'AC_SET') {
    if (extra && extra.temp !== undefined) devices[deviceId].state.temperature = extra.temp;
    if (extra && extra.fan_speed !== undefined) devices[deviceId].state.fan_speed = extra.fan_speed;
}
global.set('devices', devices);

msg._hmi_cmd = { deviceId, action, extra };
return msg;
